import { describe, expect, it, vi } from 'vitest'
import { http, HttpResponse } from 'msw'
import { getAppointments } from '@/api/appointments'
import { server } from '../mocks/server'
import {
  CALENDAR_APPOINTMENTS_URL,
  rawAppointmentsFixture,
} from '../mocks/handlers/calendar'

describe('getAppointments — fetch wrapper', () => {
  it('sorts raw appointments ascending by sort_index and maps via toAppointment', async () => {
    const result = await getAppointments()

    expect(result).toHaveLength(2)
    // raw fixture is unsorted ([3, 1]); wrapper sorts ascending via bySortIndex
    expect(result[0].title).toBe('Jahreshauptversammlung')
    expect(result[0].startDateISO).toBe('2024-01-15')
    expect(result[0].endDateISO).toBe('2024-01-15')
    expect(result[1].title).toBe('Pokalspiel')
    expect(result[1].startDateISO).toBe('2024-05-11T15:00:00')
  })

  it('returns an empty array when the backend responds with []', async () => {
    server.use(http.get(CALENDAR_APPOINTMENTS_URL, () => HttpResponse.json([])))
    expect(await getAppointments()).toEqual([])
  })

  it('throws a descriptive error on non-2xx (404)', async () => {
    server.use(
      http.get(CALENDAR_APPOINTMENTS_URL, () =>
        HttpResponse.json({ message: 'not found' }, { status: 404 }),
      ),
    )
    await expect(getAppointments()).rejects.toThrow(
      'Failed to load appointments: 404 Not Found',
    )
  })

  it('throws on a 500 response', async () => {
    server.use(
      http.get(CALENDAR_APPOINTMENTS_URL, () =>
        HttpResponse.json({ message: 'boom' }, { status: 500 }),
      ),
    )
    await expect(getAppointments()).rejects.toThrow(
      'Failed to load appointments: 500 Internal Server Error',
    )
  })

  it('hits the canonical calendar appointments endpoint with GET (request shape)', async () => {
    const spy = vi.fn(() => HttpResponse.json([]))
    server.use(http.get(CALENDAR_APPOINTMENTS_URL, spy))

    await getAppointments()

    expect(spy).toHaveBeenCalledTimes(1)
    const [call] = spy.mock.calls
    expect(call[0].request.method).toBe('GET')
    expect(new URL(call[0].request.url).pathname).toBe('/api/calendar/appointments')
  })

  it('does not leak the unsorted raw shape — every entry is an Appointment', async () => {
    const result = await getAppointments()
    for (const appt of result) {
      expect(typeof appt.date).toBe('string')
      expect(typeof appt.time).toBe('string')
      expect(typeof appt.title).toBe('string')
    }
    // sanity: the fixture round-trips with the same number of items
    expect(result).toHaveLength(rawAppointmentsFixture.length)
  })
})

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { http, HttpResponse } from 'msw'
import { EventType, type Booking } from '@/types'
import {
  bookEvent,
  loadEventAvailability,
  loadEvents,
  loadEventsAvailability,
  prebooking,
  prebookWithIban,
  type AvailabilityState,
  availabilityState,
} from '@/api/events'
import { server } from '../mocks/server'
import {
  EVENTS_BOOKING_URL,
  EVENTS_COUNTER_URL,
  EVENTS_URL,
  bookingSuccessNoCounters,
  bookingSuccessResponse,
  prebookingSuccessNoIbanResponse,
  prebookingSuccessResponse,
  rawCounterFixture,
  rawEventFixture,
} from '../mocks/handlers/events'

/**
 * `loadEvents` interpolates `PREVIEW` (from `astro:env/client`) into the `beta`
 * query param. The default static export can't be stubbed at call time, so this
 * mock exposes `PREVIEW` as a getter that reads `import.meta.env.PREVIEW`,
 * letting `vi.stubEnv('PREVIEW', …)` flip the branch per test. The fallback
 * (`?? false`) mirrors the production default baked into `astro:env/client` from
 * `.env` (`PREVIEW=false`).
 */
vi.mock('astro:env/client', async (importOriginal) => {
  const orig = await importOriginal<typeof import('astro:env/client')>()
  return {
    ...orig,
    get PREVIEW(): boolean {
      return (import.meta.env.PREVIEW as unknown as boolean | undefined) ?? false
    },
  }
})

const EVENT_ID = 'evt-1'

const sampleBooking: Booking = {
  event_id: EVENT_ID,
  first_name: 'Lisa',
  last_name: 'Müller',
  street: 'Hauptstr. 1',
  city: 'Eutingen',
  email: 'lisa@example.org',
  phone: '01761234567',
  member: true,
  updates: false,
  comments: 'keine',
  custom_values: [],
}

/** Expected availability for `rawCounterFixture` (slots=7, no waiting list). */
const expectedAvailabilityForFixture = {
  availableSlots: 7,
  isWaitingList: false,
  message: 'Noch 7 freie Plätze',
}

describe('loadEvents — fetch wrapper', () => {
  it('maps RawEvent[] to Event[] with the calendar-aware shape', async () => {
    const result = await loadEvents(EventType.Fitness)
    expect(result).toHaveLength(1)
    expect(result[0]).toEqual({
      id: 'evt-1',
      name: 'Rückenfit',
      image: '/src/assets/events/rueckenfit.jpg',
      sortIndex: 1,
      shortDescription: 'Pilates für den Rücken',
      description: 'Ein sanfter Kurs',
      location: 'Clubhaus',
      dates: ['2024-04-08T18:00:00', '2024-04-15T18:00:00'],
      datesDisplay: expect.any(String),
      duration: 'Kurslänge: 1 Stunde',
      priceMember: '40,00\u00A0€',
      priceNonMember: '60,00\u00A0€',
      externalOperator: false,
      altBookingButtonText: undefined,
      customFields: [{ name: 'Rückenbeschwerden', type: 'Text' }],
      paymentMethod: 'SepaDirectDebit',
    })
  })

  it('keeps only events whose `type` matches the requested type', async () => {
    server.use(
      http.get(EVENTS_URL, () =>
        HttpResponse.json([
          rawEventFixture,
          { ...rawEventFixture, id: 'evt-2', type: 'Events', sort_index: 2 },
        ]),
      ),
    )
    const result = await loadEvents(EventType.Fitness)
    expect(result.map((e) => e.id)).toEqual(['evt-1'])
  })

  it('sorts events ascending by sort_index before mapping', async () => {
    server.use(
      http.get(EVENTS_URL, () =>
        HttpResponse.json([
          { ...rawEventFixture, id: 'evt-b', sort_index: 5 },
          { ...rawEventFixture, id: 'evt-a', sort_index: 1 },
        ]),
      ),
    )
    const result = await loadEvents(EventType.Fitness)
    expect(result.map((e) => e.id)).toEqual(['evt-a', 'evt-b'])
  })

  it('ships a stable datesDisplay for a single-date event (custom_date passthrough)', async () => {
    server.use(
      http.get(EVENTS_URL, () => HttpResponse.json([{ ...rawEventFixture, custom_date: 'Individuell' }])),
    )
    expect((await loadEvents(EventType.Fitness))[0].datesDisplay).toBe('Individuell')
  })

  it('throws a descriptive error on non-2xx (500)', async () => {
    server.use(http.get(EVENTS_URL, () => HttpResponse.json({ msg: 'boom' }, { status: 500 })))
    await expect(loadEvents(EventType.Fitness)).rejects.toThrow('Failed to load events: 500 Internal Server Error')
  })

  describe('PREVIEW query branch (vi.stubEnv)', () => {
    it('sends beta=false by default (the .env default)', async () => {
      const spy = vi.fn(() => HttpResponse.json([]))
      server.use(http.get(EVENTS_URL, spy))

      await loadEvents(EventType.Fitness)

      expect(spy).toHaveBeenCalledTimes(1)
      const url = new URL(spy.mock.calls[0][0].request.url)
      expect(url.searchParams.get('type')).toBe('Fitness')
      expect(url.searchParams.get('beta')).toBe('false')
    })

    it('sends beta=true when PREVIEW is stubbed true', async () => {
      vi.stubEnv('PREVIEW', true)
      const spy = vi.fn(() => HttpResponse.json([]))
      server.use(http.get(EVENTS_URL, spy))

      await loadEvents(EventType.Events)

      expect(spy).toHaveBeenCalledTimes(1)
      const url = new URL(spy.mock.calls[0][0].request.url)
      expect(url.searchParams.get('type')).toBe('Events')
      expect(url.searchParams.get('beta')).toBe('true')
    })
  })
})

describe('loadEventsAvailability — fetch + sessionStorage cache', () => {
  beforeEach(() => {
    sessionStorage.clear()
  })

  it('on a cache miss, fetches counters, invokes callback with fresh data and writes the cache', async () => {
    const callback = vi.fn()
    await loadEventsAvailability(callback)

    expect(callback).toHaveBeenCalledTimes(1)
