import { describe, expect, it } from 'vitest'
import { http, HttpResponse } from 'msw'
import { getAppointments } from '@/api/appointments'
import { server } from '../mocks/server'
import { CALENDAR_APPOINTMENTS_URL } from '../mocks/handlers/calendar'

describe('getAppointments — fetch wrapper', () => {
  it('sorts raw appointments ascending by sort_index and maps via toAppointment', async () => {
    const result = await getAppointments()

    expect(result).toHaveLength(2)
    expect(result[0].title).toBe('Jahreshauptversammlung')
    expect(result[0].startDateISO).toBe('2024-01-15')
    expect(result[0].endDateISO).toBe('2024-01-15')
    expect(result[1].title).toBe('Pokalspiel')
    expect(result[1].startDateISO).toBe('2024-05-11T15:00:00')
  })

  it('returns an empty array when the backend responds with []', async () => {
    server.use(http.get(CALENDAR_APPOINTMENTS_URL, () => HttpResponse.json([])))
    expect(await getAppointments()).toEqual([])
  })

  it('throws a descriptive error on non-2xx (404)', async () => {
    server.use(
      http.get(CALENDAR_APPOINTMENTS_URL, () =>
        HttpResponse.json({ message: 'not found' }, { status: 404 }),
      ),
    )
    await expect(getAppointments()).rejects.toThrow(
      'Failed to load appointments: 404 Not Found',
    )
  })

  it('throws on a 500 response', async () => {
    server.use(
      http.get(CALENDAR_APPOINTMENTS_URL, () =>
        HttpResponse.json({ message: 'boom' }, { status: 500 }),
      ),
    )
    await expect(getAppointments()).rejects.toThrow(
      'Failed to load appointments: 500 Internal Server Error',
    )
  })

  it('hits the canonical calendar appointments endpoint with GET (request shape)', async () => {
    let capturedRequest: Request | undefined
    server.use(
      http.get(CALENDAR_APPOINTMENTS_URL, ({ request }) => {
        capturedRequest = request
        return HttpResponse.json([])
      }),
    )

    await getAppointments()

    expect(capturedRequest!.method).toBe('GET')
    expect(new URL(capturedRequest!.url).pathname).toBe('/api/calendar/appointments')
  })
})

import { describe, expect, it } from 'vitest'
import { http, HttpResponse } from 'msw'
import { manageSubscription, sendContactMessage } from '@/api/forms'
import { server } from '../mocks/server'
import {
  CONTACT_MESSAGE_URL,
  NEWS_SUBSCRIBE_URL,
  NEWS_UNSUBSCRIBE_URL,
} from '../mocks/handlers/forms'

describe('sendContactMessage — mutating POST contact route', () => {
  it('asserts request shape: URL, POST, Content-Type application/json, body shape {type, to, name, email, phone, message, token}', async () => {
    let capturedMethod: string | undefined = undefined
    let capturedContentType: string | null = null
    let capturedUrl: string | undefined = undefined
    let capturedBody: any = undefined
    server.use(
      http.post(CONTACT_MESSAGE_URL, async ({ request }) => {
        capturedMethod = request.method
        capturedContentType = request.headers.get('Content-Type')
        capturedUrl = request.url
        capturedBody = await request.json()
        return HttpResponse.json({ success: true, message: 'sent' })
      }),
    )

    const response = await sendContactMessage(
      'vorstand@sv-eutingen.de',
      '  Max Mustermann  ',
      '  max@example.org  ',
      ' 0176 1234567 ',
      '  Hallo Welt  ',
      'captcha-token',
    )

    expect(response.ok).toBe(true)
    expect(capturedMethod).toBe('POST')
    expect(new URL(capturedUrl!).pathname).toBe('/api/contact/message')
    expect(capturedContentType).toBe('application/json')
    expect(capturedBody).toEqual({
      type: 'General',
      to: 'vorstand@sv-eutingen.de',
      name: 'Max Mustermann',
      email: 'max@example.org',
      phone: '0176 1234567',
      message: 'Hallo Welt',
      token: 'captcha-token',
    })
  })

  it('omits phone (sets it undefined) when the caller passes `undefined`', async () => {
    let capturedBody: any
    server.use(
      http.post(CONTACT_MESSAGE_URL, async ({ request }) => {
        capturedBody = await request.json()
        return HttpResponse.json({ success: true })
      }),
    )

    await sendContactMessage('recip', 'Max', 'max@example.org', undefined, 'msg', 'tok')

    expect(capturedBody).toEqual({
      type: 'General',
      to: 'recip',
      name: 'Max',
      email: 'max@example.org',
      phone: undefined,
      message: 'msg',
      token: 'tok',
    })
  })

  it('returns the raw 2xx Response (caller proceeds with response.ok)', async () => {
    server.use(http.post(CONTACT_MESSAGE_URL, () => HttpResponse.json({ success: true })))

    const response = await sendContactMessage('to', 'n', 'e', undefined, 'm', 't')
    expect(response.ok).toBe(true)
    expect(response.status).toBe(200)
  })

  it('failure path: returns the raw non-2xx Response without throwing', async () => {
    server.use(
      http.post(CONTACT_MESSAGE_URL, () =>
        HttpResponse.json({ message: 'invalid' }, { status: 422 }),
      ),
    )

    const response = await sendContactMessage('to', 'n', 'e', undefined, 'm', 't')
    expect(response.ok).toBe(false)
    expect(response.status).toBe(422)
  })

  it('failure path: 500 also surfaces as raw Response', async () => {
    server.use(http.post(CONTACT_MESSAGE_URL, () => HttpResponse.json({}, { status: 500 })))
    const response = await sendContactMessage('to', 'n', 'e', undefined, 'm', 't')
    expect(response.ok).toBe(false)
    expect(response.status).toBe(500)
  })
})

